class ServiceA:
    def process(self, data):
        return f'Processed by A: {data}'

class ServiceB:
    def __init__(self, service_a):
        self.service_a = service_a

    def handle(self, data):
        result = self.service_a.process(data)
        return f'B received -> {result}'

service_a = ServiceA()
service_b = ServiceB(service_a)

print(service_b.handle('data'))

class EventBus:
    def __init__(self):
        self.listeners = {}

    def subscribe(self, event, fn):
        self.listeners.setdefault(event, []).append(fn)

    def emit(self, event, data):
        for fn in self.listeners.get(event, []):
            fn(data)

bus = EventBus()

bus.subscribe('user_created', lambda d: print(f'User: {d}'))
bus.emit('user_created', {'id': 1})

